       content: var(--icon-address-book-new-lg);
     }

-    & .ldap-address-book-icon {
+    &.ldap-address-book-icon {
       content: var(--addons-manager-site-permissions);
     }
   }

-  & .option-content {
-    display: flex;
-    flex-direction: column;
-    align-items: start;
-    gap: 1px;
+  & .option-title {
+    grid-column: 2;
+    grid-row: 1;
+    font-size: 1.54rem;
+    color: var(--color-primary-hover);
+    font-weight: 400;
+    text-align: start;
+  }

-    & .option-title {
-      font-size: 1.54rem;
-      color: var(--color-primary-hover);
-      font-weight: 400;
-    }
+  & .option-data {
