+    grid-row: 2;
+    font-size: 1rem;
+    font-weight: 500;
+    color: var(--color-text-secondary);
+    text-align: start;
+  }

-    & .option-data {
-      font-size: 1rem;
-      font-weight: 500;
-      color: var(--color-text-secondary);
-      text-align: start;
-    }
+  & .account-address-book-count {
